package com.bank.manager;

import java.util.*;
import java.util.logging.*;

public class ManagerDemo {
    private static final Logger log = Logger.getLogger("Manager");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        ManagerLookup lookup = new ManagerLookup();

        Account withManager = new Account("SAV2001",
            new Branch("Mumbai", "rajesh verma"));
        Account noManager = new Account("CUR3001", new Branch("Delhi", "  "));
        Account noBranch = new Account("SAV9999", null);

        log.info(() -> "With manager: " + lookup.managerName(Optional.of(withManager)));
        log.info(() -> "Blank manager: " + lookup.managerName(Optional.of(noManager)));
        log.info(() -> "No branch: " + lookup.managerName(Optional.of(noBranch)));
        log.info(() -> "No account: " + lookup.managerName(Optional.empty()));
    }
}

// ─── Would be in model/Branch.java ───
class Branch {
    private final String city;
    private final String manager;   // may be blank
    Branch(String city, String manager) { this.city = city; this.manager = manager; }
    String getManager() { return manager; }
}

// ─── Would be in model/Account.java ───
class Account {
    private final String id;
    private final Branch branch;    // may be null
    Account(String id, Branch branch) { this.id = id; this.branch = branch; }
    Optional<Branch> getBranch() { return Optional.ofNullable(branch); } // returns Optional
}

// ─── Would be in service/ManagerLookup.java ───
class ManagerLookup {
    String managerName(Optional<Account> account) {
        return account
            .flatMap(Account::getBranch)        // flatMap: getBranch returns Optional
            .map(Branch::getManager)            // map: getManager returns a plain String
            .filter(m -> m != null && !m.isBlank())  // drop blank managers
            .map(String::toUpperCase)           // map: transform to uppercase
            .orElse("NO MANAGER");              // default if any step was empty
    }
}
